%添加java系统路径和java包jar，加载依赖库
if(ispc())
    jarPath = [pwd,'\ATKComponentJava.jar']
elseif(isunix())
    jarPath = [pwd,'/ATKComponentJava.jar']
end
if ~any(strcmp(jarPath,javaclasspath()))
    javaaddpath(jarPath)
    javaMethod('loadLibrary', 'ATKLibraryLoader');
end

%获取公用接口模块
pATKComponentJavaModule= javaObject('com.atk.component.ATKComponentJavaModule')
pATKComponentJavaModule.SetSaveFileBasePath(pwd);
pATKComponentJavaModule.SetCallCodeType('Octave');

